class Solution:
    def maxNumOfMarkedIndices(self, nums: List[int]) -> int:
        nums.sort()
        i = 0
        for j in range((len(nums) + 1) // 2, len(nums)):
            if 2 * nums[i] <= nums[j]:
                i += 1
        return 2 * i

