class Solution {
public:
    int maxNumOfMarkedIndices(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size(), i = 0;
        for (int j = (n + 1) / 2; j < n; j++)
            if (2L * nums[i] <= nums[j]) i++;
        return 2 * i;
    }
};

