class Solution {
public:
    int maxNumOfMarkedIndices(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        auto ok = [&](int p) {
            for (int t = 0; t < p; t++)
                if (2L * nums[t] > nums[n - p + t]) return false;
            return true;
        };
        int lo = 0, hi = n / 2;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid; else hi = mid - 1;
        }
        return 2 * lo;
    }
};

