class Solution {
    public int maxNumOfMarkedIndices(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length, lo = 0, hi = n / 2;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            boolean good = true;
            for (int t = 0; t < mid; t++)
                if (2L * nums[t] > nums[n - mid + t]) { good = false; break; }
            if (good) lo = mid; else hi = mid - 1;
        }
        return 2 * lo;
    }
}

